CREATE TYPE claim_status AS ENUM ('draft','claiming','review','approved','cancelled');
CREATE TABLE receipt_claims(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tab_id uuid NOT NULL REFERENCES tabs(id) ON DELETE CASCADE,payer_id uuid NOT NULL REFERENCES users(id),merchant text,receipt_image_url text,currency text NOT NULL,receipt_total numeric(18,2) NOT NULL,status claim_status NOT NULL DEFAULT 'draft',created_at timestamptz NOT NULL DEFAULT now(),finalized_at timestamptz);
CREATE TABLE receipt_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),claim_id uuid NOT NULL REFERENCES receipt_claims(id) ON DELETE CASCADE,label text NOT NULL,quantity numeric(10,3) NOT NULL DEFAULT 1,unit_price numeric(18,2),line_total numeric(18,2) NOT NULL,extraction_confidence numeric(5,4),position int NOT NULL);
CREATE TABLE item_claims(item_id uuid NOT NULL REFERENCES receipt_items(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES users(id),share_quantity numeric(10,3) NOT NULL DEFAULT 1,claimed_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(item_id,user_id));
CREATE TABLE receipt_approvals(claim_id uuid NOT NULL REFERENCES receipt_claims(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES users(id),approved_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(claim_id,user_id));
CREATE INDEX receipt_claims_tab_idx ON receipt_claims(tab_id); CREATE INDEX receipt_items_claim_idx ON receipt_items(claim_id);